parameters.code:
// Format GitHub data into a structured summary for Claude
const commits = $input.all()[0]?.json?.commits || [];
const issues = $input.all()[0]?.json?.issues || [];
const pulls = $input.all()[0]?.json?.pulls || [];

// Filter merged PRs
const mergedPRs = (pulls || []).filter(p => p.merged_at);

// Categorize commits by type
const categorizedCommits = {
  features: commits.filter(c => c.commit.message.startsWith('feat')),
  fixes: commits.filter(c => c.commit.message.startsWith('fix')),
  docs: commits.filter(c => c.commit.message.startsWith('docs')),
  other: commits.filter(c => !c.commit.message.match(/^(feat|fix|docs|chore|refactor|test)/))
};

return [{
  json: {
    repo: $json.repo || 'N/A',
    weekRange: `${$json.since} to ${$json.until}`,
    stats: {
      totalCommits: commits.length,
      closedIssues: issues.length,
      mergedPRs: mergedPRs.length,
      contributors: [...new Set(commits.map(c => c.commit.author?.name || 'Unknown'))],
      topContributor: Object.entries(
        commits.reduce((acc, c) => {
          const name = c.commit.author?.name || 'Unknown';
          acc[name] = (acc[name] || 0) + 1;
          return acc;
        }, {})
      ).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A'
    },
    categorizedCommits,
    recentIssues: issues.slice(0, 10).map(i => ({
      title: i.title,
      number: i.number,
      state: i.state,
      labels: i.labels?.map(l => l.name).join(', ') || ''
    })),
    recentPRs: mergedPRs.slice(0, 10).map(pr => ({
      title: pr.title,
      number: pr.number,
      author: pr.user?.login || 'unknown',
      additions: pr.additions || 0,
      deletions: pr.deletions || 0
    }))
  }
}];

